  void searchConversation(){showPage(false);EditText query=new EditText(this);query.setSingleLine(true);query.setHint("搜索已加载的全部消息");TextView count=label("按消息显示搜索结果",13,Ui.MUTED);LinearLayout box=new LinearLayout(this);box.setOrientation(1);box.setPadding(dp(20),dp(12),dp(20),0);box.addView(query);box.addView(count);long[] serial={0};java.util.function.IntConsumer find=step->{long request=++serial[0];reader.evaluateJavascript("JSON.stringify(window.chat.search("+JSONObject.quote(query.getText().toString())+","+step+"))",raw->{if(request!=serial[0])return;try{JSONObject result=new JSONObject((String)new JSONTokener(raw).nextValue());int total=result.optInt("total");count.setText(total==0?"没有匹配（仅搜索已加载内容）":"第 "+result.optInt("index")+" / "+total+" 条匹配消息");}catch(Exception ignored){count.setText("搜索暂不可用");}});};AlertDialog d=new AlertDialog.Builder(this).setTitle("对话内搜索").setView(box).setPositiveButton("下一条",null).setNeutralButton("上一条",null).setNegativeButton("关闭",null).create();query.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void afterTextChanged(Editable e){}public void onTextChanged(CharSequence s,int a,int b,int c){find.accept(0);}});d.setOnShowListener(v->{d.getButton(-1).setOnClickListener(w->find.accept(1));d.getButton(-3).setOnClickListener(w->find.accept(-1));});d.setOnDismissListener(v->{serial[0]++;reader.evaluateJavascript("window.chat.endSearch()",null);});d.show();d.getWindow().setDimAmount(0);d.getWindow().setGravity(Gravity.TOP);}
