  JSONArray recentChats(){JSONArray list=conversations.list();if(!prefs.getBoolean("historyMigrated",false)){try{conversations.merge(new JSONArray(prefs.getString("recentChats","[]")),false);list=conversations.list();prefs.edit().putBoolean("historyMigrated",true).apply();}catch(Exception ignored){}}return list;}
