  void switchConversation(String url){if(!attachments.allowNavigation(()->switchConversation(url)))return;if(pending!=null||submitting||session.operation){status("请先完成当前任务");return;}if(AppPrefs.enabled(this,"saveDraft"))conversations.draft(conversation,input.getText().toString());input.setText(AppPrefs.enabled(this,"saveDraft")?conversations.draft(url):"");if(drawer!=null)drawer.dismiss();session.navigate(url,"正在打开对话…");showPage(prefs.getBoolean("pageMode",false));}
  LinearLayout drawerRow(String glyph,String text,Runnable action){LinearLayout row=sheetRow(glyph,text,action);TextView label=(TextView)row.getChildAt(row.getChildCount()-1);label.setTextSize(14);label.getLayoutParams().height=dp(36);row.setPadding(dp(12),0,dp(12),0);if(row.getChildCount()>1&&row.getChildAt(0) instanceof ImageView){row.getChildAt(0).getLayoutParams().width=dp(20);row.getChildAt(0).getLayoutParams().height=dp(20);}return row;}
  void showDrawer(){
    drawer=new Dialog(this);LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(10),dp(10),dp(10),dp(12));panel.setBackgroundColor(Ui.PAPER);
    LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);TextView name=label("ChatGPT",18,Ui.INK);name.setTypeface(android.graphics.Typeface.create("sans-serif-medium",0));name.setPadding(dp(12),0,0,0);bar.addView(name,new LinearLayout.LayoutParams(0,dp(48),1));Ui.IconButton close=new Ui.IconButton(this,"close","关闭会话列表",false);bar.addView(close,new LinearLayout.LayoutParams(dp(44),dp(44)));close.setOnClickListener(v->drawer.dismiss());panel.addView(bar);
    EditText search=new EditText(this);search.setSingleLine(true);search.setTextSize(14);search.setHint("搜索聊天");search.setIncludeFontPadding(false);search.setHintTextColor(0xff808080);search.setPadding(dp(16),0,dp(12),0);search.setBackground(Ui.shape(this,0xffeeeeee,12));LinearLayout.LayoutParams searchLayout=new LinearLayout.LayoutParams(-1,dp(40));searchLayout.setMargins(dp(5),dp(10),dp(5),dp(12));panel.addView(search,searchLayout);
    panel.addView(drawerRow("new","新对话",()->newChat()));TextView recent=label("最近聊天",12,Ui.MUTED);recent.setPadding(dp(12),dp(20),0,dp(6));panel.addView(recent);
    ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);LinearLayout chats=new LinearLayout(this);chats.setOrientation(1);scroll.addView(chats);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
    Runnable refresh=()->{chats.removeAllViews();String query=search.getText().toString().trim().toLowerCase(Locale.ROOT);JSONArray list=recentChats();int count=0;for(int i=0;i<list.length();i++){JSONObject chat=list.optJSONObject(i);if(chat==null)continue;String title=chat.optString("title","未命名对话"),url=chat.optString("url");if(!title.toLowerCase(Locale.ROOT).contains(query))continue;LinearLayout row=drawerRow("",title,()->{if(pending!=null||submitting){Toast.makeText(this,"请先确认上次发送状态",Toast.LENGTH_SHORT).show();return;}switchConversation(url);});row.setOnLongClickListener(v->{FeatureDialogs.chatActions(this,chat,()->{if(drawer!=null)drawer.dismiss();showDrawer();});return true;});TextView rowTitle=(TextView)row.getChildAt(row.getChildCount()-1);rowTitle.setTextSize(14);rowTitle.setTypeface(android.graphics.Typeface.create("sans-serif",0));rowTitle.getLayoutParams().height=dp(36);row.setPadding(dp(12),0,dp(12),0);if(url.equals(conversation))row.setBackground(Ui.ripple(this,0xffe9e9e9,12));chats.addView(row);count++;}if(count==0){TextView empty=label(query.isEmpty()?"这里会显示你最近打开的对话":"没有找到匹配的对话",14,Ui.MUTED);empty.setPadding(dp(14),dp(14),dp(14),0);chats.addView(empty);}};
    search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){refresh.run();}public void afterTextChanged(Editable e){}});refresh.run();panel.addView(drawerRow("chat","同步全部历史",()->FeatureDialogs.syncHistory(this,refresh)),3);
    panel.addView(drawerRow("chat","网页历史",()->{drawer.dismiss();showPage(true);if(chatUrl(remote.getUrl()))remote.evaluateJavascript("(()=>{const b=[...document.querySelectorAll('button')].find(x=>/^(Open sidebar|打开边栏|打开侧边栏)$/.test(x.getAttribute('aria-label')||''));if(b)b.click()})()",null);}));
    View divider=new View(this);divider.setBackgroundColor(0xffeeeeee);panel.addView(divider,new LinearLayout.LayoutParams(-1,dp(1)));panel.addView(drawerRow("settings","设置",()->{drawer.dismiss();menu();}));TextView account=label("元婴期院士 · "+Profiles.display(this,Profiles.slot(this)),12,Ui.MUTED);account.setPadding(dp(14),0,0,dp(8));panel.addView(account);
    drawer.setContentView(panel);Window w=drawer.getWindow();w.setBackgroundDrawable(new android.graphics.drawable.ColorDrawable(Ui.PAPER));w.setDimAmount(.25f);w.addFlags(WindowManager.LayoutParams.FLAG_DIM_BEHIND);w.setGravity(Gravity.LEFT|Gravity.TOP);w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);drawer.show();w.setLayout(Math.min(dp(260),(int)(getResources().getDisplayMetrics().widthPixels*.88)),-1);
    if(AppPrefs.enabled(this,"autoHistory"))runDriver("chats",new JSONObject(),result->{JSONArray remoteChats=result.optJSONArray("chats");if(remoteChats!=null&&remoteChats.length()>0){mergeChats(remoteChats);if(drawer.isShowing())refresh.run();}});
  }
  void localActions(){if(!readerReady)return;reader.evaluateJavascript("JSON.stringify((window.pocketActions||[]).splice(0,20))",raw->{try{String s=(String)new JSONTokener(raw).nextValue();JSONArray a=new JSONArray(s);for(int i=0;i<a.length();i++){JSONObject item=a.getJSONObject(i);String action=item.optString("action"),text=item.optString("text");if(item.has("conversation")&&!conversation.equals(item.optString("conversation")))continue;if(action.equals("delivery-action")||(action.equals("message-menu")&&item.optString("id").startsWith("local:"))){DeliveryUi.show(this,item.optString("id").replaceFirst("^local:",""));continue;}if(action.equals("edit-message")){JSONObject e=messageActions.entry(item.optString("id"));if(e!=null)messageActions.edit(e);continue;}if(action.equals("regenerate-message")){messageActions.regenerate(item.optString("id"));continue;}if(action.equals("message-menu")){messageActions.menu(item.optString("id"));continue;}if(action.equals("download-file")){downloads.open(item.optString("id"),text);continue;}if(action.equals("older")){loadOlder();continue;}if(action.equals("preview")){attachments.preview(item.optString("id"),text);continue;}if(action.equals("open-link")){String link=text;new AlertDialog.Builder(this).setMessage(link).setPositiveButton("用浏览器打开",(d,w)->{try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(link)));}catch(Exception ignored){}}).setNegativeButton("取消",null).show();continue;}if(text.isEmpty())for(int j=0;j<entries.length();j++)if(entries.getJSONObject(j).optString("id").equals(item.optString("id")))text=entries.getJSONObject(j).optString("text");if(action.equals("export-message")){Intent share=new Intent(Intent.ACTION_SEND).setType("text/plain").putExtra(Intent.EXTRA_TEXT,text);startActivity(Intent.createChooser(share,"分享回复"));}else{((android.content.ClipboardManager)getSystemService(CLIPBOARD_SERVICE)).setPrimaryClip(ClipData.newPlainText("回复",text));Toast.makeText(this,"已复制",Toast.LENGTH_SHORT).show();}}}catch(Exception ignored){}});}
  void menu(){
    String[] choices={"编辑当前环境","当前环境网络","环境自检","管理全部环境","应用设置","重新加载网页","确认上次发送状态"};
    new AlertDialog.Builder(this).setTitle("环境 · "+Profiles.display(this,Profiles.slot(this))).setItems(choices,(d,n)->{
      if(n==0)EnvironmentEditorUi.show(this);if(n==1)hub.select(4);if(n==2)EnvironmentAuditUi.show(this);if(n==3)ProfileUi.show(this);if(n==4)hub.select(3);if(n==5)session.retryCurrent();
      if(n==6){showPage(true);new AlertDialog.Builder(this).setMessage("先查看网页确认上次提问是否已经发送。解除等待不会重发，草稿会保留。").setPositiveButton("已核对，解除等待",(x,y)->session.abandonWait()).setNegativeButton("继续等待",null).show();}
    }).setNegativeButton("关闭",null).show();
  }
  void openNotification(Intent intent){if(intent==null)return;String windowAction=intent.getStringExtra("openWindowAction");if(windowAction!=null){intent.removeExtra("openWindowAction");if(intent.getBooleanExtra("forceWebMode",false)){intent.removeExtra("forceWebMode");showPage(true);}if(hub!=null){hub.show("settings".equals(windowAction)?3:"network".equals(windowAction)?4:0);if("network".equals(windowAction))hub.network();}if("edit".equals(windowAction))handler.postDelayed(()->EnvironmentEditorUi.show(this),200);}if(intent.getBooleanExtra("openEnvironmentEditor",false)){intent.removeExtra("openEnvironmentEditor");handler.postDelayed(()->EnvironmentEditorUi.show(this),200);}String download=intent.getStringExtra("openDownload");if(download!=null){intent.removeExtra("openDownload");if(hub!=null)hub.select(1);for(int i=0;i<downloads.tasks.rows.length();i++){JSONObject row=downloads.tasks.rows.optJSONObject(i);if(download.equals(row.optString("id"))){downloads.taskActions(row);break;}}return;}String url=intent.getStringExtra("openConversation");if(!chatUrl(url))return;intent.removeExtra("openConversation");if(hub!=null)hub.select(0);
    if(session.pending!=null||session.submitting||session.operation){status("当前有未完成请求，请先完成等待再打开其他对话");return;}
    if(session.networkReady){if(WebReplyObserver.same(url,remote.getUrl())&&!session.navigationFailed){session.sync();showPage(prefs.getBoolean("pageMode",false));}else switchConversation(url);}
    else{session.requestedConversation=url;session.conversation=url;conversation=url;session.connect();}
  }
  @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);openNotification(intent);}
  @Override protected void onResume(){super.onResume();active=true;AppPrefs.maintainCache(this);if(session!=null){session.add(sessionObserver);session.audit.refresh(true);session.foreground(true);session.connect();}if(hub!=null&&hub.page!=0){hub.refresh();handler.removeCallbacks(hub.tick);handler.postDelayed(hub.tick,2500);}handler.removeCallbacks(ticker);handler.post(ticker);}
  @Override protected void onPause(){super.onPause();if(conversations!=null&&input!=null)if(AppPrefs.enabled(this,"saveDraft"))conversations.draft(conversation,input.getText().toString());active=false;NativeNetwork.get(this).traffic.watch(false);handler.removeCallbacks(ticker);CookieManager.getInstance().flush();if(session!=null){session.remove(sessionObserver);session.audit.cancel();session.foreground(false);}}
  @Override protected void onDestroy(){destroyed=true;if(networkDialog!=null)networkDialog.dismiss();if(draftUi!=null)draftUi.destroy();if(downloads!=null)downloads.destroy();if(attachments!=null)attachments.destroy();if(loading!=null)loading.dismissTask();if(hub!=null)hub.networkWorkspace.close();handler.removeCallbacksAndMessages(null);if(session!=null){session.remove(sessionObserver);session.operation=false;}if(remote!=null&&remote.getParent() instanceof ViewGroup)((ViewGroup)remote.getParent()).removeView(remote);if(reader!=null)reader.destroy();super.onDestroy();}
  @Override public void onBackPressed(){if(hub!=null&&hub.page!=0){hub.select(0);return;}if(session!=null&&session.pending!=null&&!pageMode){moveTaskToBack(true);return;}if(pageMode){showPage(false);return;}super.onBackPressed();}
